import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.dgpN-s4-.js";var i=JSON.parse(`{"title":"Owner-feedback research and follow-up decisions","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/OWNER-FEEDBACK-RESEARCH.html"}],["meta",{"property":"og:title","content":"Owner-feedback research and follow-up decisions | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/OWNER-FEEDBACK-RESEARCH.html"}],["meta",{"name":"twitter:title","content":"Owner-feedback research and follow-up decisions | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"audits/OWNER-FEEDBACK-RESEARCH.md","filePath":"audits/OWNER-FEEDBACK-RESEARCH.md","lastUpdated":1794227887000}`),a={name:`audits/OWNER-FEEDBACK-RESEARCH.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="owner-feedback-research-and-follow-up-decisions" tabindex="-1">Owner-feedback research and follow-up decisions <a class="header-anchor" href="#owner-feedback-research-and-follow-up-decisions" aria-label="Permalink to “Owner-feedback research and follow-up decisions”">​</a></h1><p><strong>Research date:</strong> 9 November 2026<br><strong>Implementation branch:</strong> <code>audit/owner-feedback-followups</code><br><strong>Target:</strong> <code>dev</code><br><strong>Scope:</strong> owner-approved follow-ups from the 9 November 2026 audit review. This document records researched facts, chosen behaviour, implementation boundaries and items deliberately left unchanged.</p><h2 id="_1-eng-01-—-installment-payouts-are-bounded-by-the-simulation-window" tabindex="-1">1. ENG-01 — installment payouts are bounded by the simulation window <a class="header-anchor" href="#_1-eng-01-—-installment-payouts-are-bounded-by-the-simulation-window" aria-label="Permalink to “1. ENG-01 — installment payouts are bounded by the simulation window”">​</a></h2><h3 id="owner-decision" tabindex="-1">Owner decision <a class="header-anchor" href="#owner-decision" aria-label="Permalink to “Owner decision”">​</a></h3><p>Do not clamp an installment schedule&#39;s last payout to contractual maturity and do not extend the simulation horizon to accommodate a later installment. Generate the product&#39;s contractual payout sequence, then include only payout events whose dates fall inside the active simulation period.</p><p>The product&#39;s contractual maturity remains a candidate-eligibility constraint: the FD must mature by the simulation end. The payout event stream is separately bounded by the same simulation window. A payout outside the window is not simulated, and the simulation end date is not moved.</p><h3 id="source-level-observation" tabindex="-1">Source-level observation <a class="header-anchor" href="#source-level-observation" aria-label="Permalink to “Source-level observation”">​</a></h3><p><code>FDOption.generateCashFlows()</code> currently generates installment dates by repeatedly adding the payout interval until the generated date is on or after maturity. A five-month tenor with a two-month interval therefore yields months 2, 4 and 6. The authoritative runtime&#39;s <code>schedule()</code> rejects any event outside <code>context.start</code>–<code>context.end</code>, so the booking path must filter the event stream before scheduling rather than allowing an out-of-window event to abort the run.</p><p>The booking&#39;s contractual interest calculation must remain based on the full product schedule. Filtering the event ledger must not accidentally recalculate total contractual interest, AIT, or installment allocation using only the in-window subset. The implementation should preserve the full contractual cash-flow calculation internally while exposing/scheduling only in-window events.</p><h3 id="acceptance-tests" tabindex="-1">Acceptance tests <a class="header-anchor" href="#acceptance-tests" aria-label="Permalink to “Acceptance tests”">​</a></h3><ul><li>5-month tenor / 2-month interval with a 5-month simulation window: only month 2 and month 4 events are scheduled; no event is added at month 6 and the simulation end remains month 5.</li><li>The same product with a 6-month simulation window: month 2, 4 and 6 events are within the requested window; product maturity remains month 5.</li><li>5-month tenor / 6-month interval with a 5-month simulation window: no payout event is scheduled within the window; the engine must handle the contract without extending the run or inventing a maturity-date payout.</li><li>Exact-divisor schedule (e.g. 6-month tenor / 2-month interval): all generated events within the simulation window are retained.</li><li>Confirm contractual interest, AIT, principal allocation and report totals do not change merely because the event window truncates later cash-flow events.</li><li>Confirm Greedy, GSS, Absolute and Absolute+ all use the same runtime event filter and replay semantics.</li></ul><p>This is a simulation-window rule, not a claim that every bank contract pays its final installment after maturity. Product-level contract wording still needs to be recorded in source notes where available.</p><h2 id="_2-eng-02-—-elapsed-day-interest-convention" tabindex="-1">2. ENG-02 — elapsed-day interest convention <a class="header-anchor" href="#_2-eng-02-—-elapsed-day-interest-convention" aria-label="Permalink to “2. ENG-02 — elapsed-day interest convention”">​</a></h2><h3 id="current-calculation" tabindex="-1">Current calculation <a class="header-anchor" href="#current-calculation" aria-label="Permalink to “Current calculation”">​</a></h3><p>The current implementation uses actual elapsed days and one denominator selected from the accrual start date&#39;s calendar year:</p><ul><li>366 when leap-year handling is enabled and the start year is a leap year.</li><li>365 otherwise.</li><li>The selected denominator is applied to the complete accrual interval, including intervals that cross into another calendar year.</li><li>Simple interest is <code>principal × annual rate × elapsed days / selected year base</code>.</li><li>Compound interest uses the same selected base as the daily compounding denominator.</li></ul><p>This is a start-year denominator convention. It is not calendar-segmented Actual/Actual. The owner has confirmed that this is intentional for FD Cal and that the formula must remain unchanged.</p><h3 id="bank-term-research-result" tabindex="-1">Bank-term research result <a class="header-anchor" href="#bank-term-research-result" aria-label="Permalink to “Bank-term research result”">​</a></h3><p>Published Sri Lankan bank product pages and key-facts documents commonly state nominal/annual effective rates, tenors and payout choices, but the reviewed public materials do not establish one universal day-count basis used by all banks. Examples:</p><ul><li><a href="https://www.hnbfinance.lk/fixed-deposits/" target="_blank" rel="noreferrer">HNB Finance — Fixed Deposits</a> describes tenure and monthly/maturity interest payout options.</li><li><a href="https://www.nsb.lk/product/ordinary-term/fixed-deposit/" target="_blank" rel="noreferrer">National Savings Bank — Fixed Deposit</a> describes monthly or maturity interest payout and available tenors.</li><li><a href="https://www.combank.lk/downloads/file/206/fixed-deposits" target="_blank" rel="noreferrer">Commercial Bank — Fixed Deposit Key Facts Document</a> describes maturity/monthly interest options and product conditions.</li></ul><p>These product pages do not, by themselves, prove that every bank uses FD Cal&#39;s start-year denominator. Do not market this as a universal Sri Lankan bank convention. Describe it as the calculation convention currently used by FD Cal, and tell users to verify a specific bank&#39;s day-count and rounding rules.</p><h3 id="owner-approved-treatment" tabindex="-1">Owner-approved treatment <a class="header-anchor" href="#owner-approved-treatment" aria-label="Permalink to “Owner-approved treatment”">​</a></h3><p>Keep the formula. Add a short, visible explanation in the UI/report and retain tests covering a leap-year start, non-leap-year start and multi-year interval crossing 29 February. Any later change to calendar-segmented Actual/Actual or a bank-specific basis requires a separate financial-model decision and before/after expected-value fixtures.</p><p>See <a href="./../finance/INTEREST-DAY-COUNT.html">Interest day-count convention</a>.</p><h2 id="_3-eng-03-—-central-product-term-validation" tabindex="-1">3. ENG-03 — central product-term validation <a class="header-anchor" href="#_3-eng-03-—-central-product-term-validation" aria-label="Permalink to “3. ENG-03 — central product-term validation”">​</a></h2><h3 id="owner-approved-direction" tabindex="-1">Owner-approved direction <a class="header-anchor" href="#owner-approved-direction" aria-label="Permalink to “Owner-approved direction”">​</a></h3><p>Centralize structural and simulation eligibility checks. A product may only be booked when its contractual maturity fits within the active simulation period. Generated cash-flow events are independently filtered to that same period as described in ENG-01.</p><p>The first validation layer should cover:</p><ul><li>Positive, parseable tenor.</li><li>Positive, parseable payout interval for non-cumulative products.</li><li>Supported payout type.</li><li>Finite, non-negative annual rate (negative-rate products require an explicit product/model decision rather than accidental acceptance).</li><li>Finite, positive minimum principal where the product requires a minimum.</li><li>Consistent age-segment metadata (age bounds ordered and within the supported range; guardian requirement explicit when known).</li><li>Maturity date within the simulation horizon at booking time.</li></ul><p>Do not add special-product maximums, tax exemptions, scheme-wide caps or channel restrictions to the generic model until the relevant product rules are researched and the simulation workflow is designed to enforce them. Invalid individual catalogue rows should be isolated with bank/file/row diagnostics where safe; they should not silently contaminate valid rows or force an entire multi-bank catalogue to be discarded without a clear fatal structural error.</p><h2 id="_4-eng-04-—-ait-assumption-deliberately-lightweight" tabindex="-1">4. ENG-04 — AIT assumption, deliberately lightweight <a class="header-anchor" href="#_4-eng-04-—-ait-assumption-deliberately-lightweight" aria-label="Permalink to “4. ENG-04 — AIT assumption, deliberately lightweight”">​</a></h2><h3 id="verified-reference" tabindex="-1">Verified reference <a class="header-anchor" href="#verified-reference" aria-label="Permalink to “Verified reference”">​</a></h3><p>The current engine assumption is 10% of interest. The primary reference is the Inland Revenue Department&#39;s <a href="https://www.ird.gov.lk/en/publications/Circulars_Circulars/SEC_2025_E_02_E.pdf" target="_blank" rel="noreferrer">Circular SEC/2025/E/02</a>, dated 28 March 2025, which states that AIT on Sri Lankan-source interest/discount payments is 10% with effect from 1 April 2025.</p><p>The IRD&#39;s <a href="https://www.ird.gov.lk/en/publications/Circulars_Circulars/SEC_2026_E_04_E.pdf" target="_blank" rel="noreferrer">Circular SEC/2026/E/04</a>, dated 8 June 2026, is the later general withholding-agent guidance; it is not a replacement for the interest-specific 2025 circular. The IRD&#39;s <a href="https://www.ird.gov.lk/en/publications/Circulars_Circulars/SEC_2025_E_03_E.pdf" target="_blank" rel="noreferrer">Circular SEC/2025/E/03</a> and current <a href="https://www.ird.gov.lk/en/sitepages/faqs.aspx" target="_blank" rel="noreferrer">AIT self-declaration FAQ</a> describe relief for resident individuals whose assessable income, including deposit interest, does not exceed LKR 1.8 million for the relevant year of assessment, subject to a declaration submitted before withholding. The declaration is valid for one year of assessment. The later <a href="https://www.ird.gov.lk/en/Lists/Latest%20News%20%20Notices/Attachments/779/SEC_PN_IT_2026-01_E.pdf" target="_blank" rel="noreferrer">IRD notice SEC/PN/IT/2026/01</a>, dated 24 March 2026, specifically addresses self-declarations for Y/A 2026/2027 and subsequent years, including the LKR 1.8 million assessable-income threshold and the need to update a declaration if circumstances change. This reinforces why the calculator must label 10% as its baseline modelling assumption and not a universal individual tax outcome. The <a href="https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/publications/aer/2025/en/29_Major_Economic_Policy_Measures.pdf" target="_blank" rel="noreferrer">CBSL Annual Economic Review 2025 policy-measures supplement</a> independently records the increase of the interest/discount AIT rate from 5% to 10%.</p><h3 id="important-qualification" tabindex="-1">Important qualification <a class="header-anchor" href="#important-qualification" aria-label="Permalink to “Important qualification”">​</a></h3><p>10% is the current baseline assumption used by FD Cal; it is not a complete determination for every depositor or every interest payment. IRD guidance also describes exemptions and resident-individual self-declaration/relief procedures. Non-resident treatment can depend on double-tax agreements and tax-clearance processes. The calculator does not currently collect tax-residency, exemption or declaration evidence and must not imply that every depositor is invariably liable for 10%.</p><h3 id="owner-approved-implementation-boundary" tabindex="-1">Owner-approved implementation boundary <a class="header-anchor" href="#owner-approved-implementation-boundary" aria-label="Permalink to “Owner-approved implementation boundary”">​</a></h3><p>Keep the model simple: a single current Sri Lankan interest AIT rate with a stable assumption identifier, effective date, verification date and official source reference. Show a concise source disclosure beside the UI toggle. Do not introduce a user-configurable tax regime, historical tax engine or product-level exemption system in this pass. Keep the current rate at 10% until an authoritative update is verified.</p><p>Current metadata identifier: <code>LK-AIT-INTEREST-2025-04-01</code>. The rate metadata and UI source link have been added on this branch; contract tests and CI verification remain.</p><h2 id="_5-data-03-—-special-fd-products-research-only-no-implementation" tabindex="-1">5. DATA-03 — special FD products: research only, no implementation <a class="header-anchor" href="#_5-data-03-—-special-fd-products-research-only-no-implementation" aria-label="Permalink to “5. DATA-03 — special FD products: research only, no implementation”">​</a></h2><p>The owner explicitly deferred workflow/model changes. Keep special products out of the active simulation catalogue unless all simulation-critical conditions can be represented and enforced.</p><h3 id="findings" tabindex="-1">Findings <a class="header-anchor" href="#findings" aria-label="Permalink to “Findings”">​</a></h3><p><strong>Government Special Fixed Deposit Scheme for Senior Citizens (2025).</strong> The Cabinet decision dated 16 June 2025 described a scheme for Sri Lankan citizens aged 60 or above, deposits opened between 1 July and 31 December 2025, a 12-month tenor, and a maximum aggregate deposit of LKR 1,000,000. The subsidised rate used a comparison formula based on AWFDR or the relevant bank&#39;s FD rate plus 3%, whichever was higher. The programme period has ended; do not present this as an open/current offer without a new official extension. Source: <a href="https://www.cabinetoffice.gov.lk/cab/index.php?Itemid=49&amp;dID=13249&amp;id=16&amp;lang=en&amp;option=com_content&amp;view=article" target="_blank" rel="noreferrer">Cabinet decision</a>.</p><p><strong>Minor FD products.</strong> Conditions are not interchangeable:</p><ul><li><a href="https://www.sdb.lk/images/pdf/kfd/sdb-minor-fd-en.pdf" target="_blank" rel="noreferrer">SDB Minor FD Key Facts Document</a> says the account is for a Sri Lankan citizen below 18 with a guardian, with a LKR 10,000 opening/minimum balance and an original certificate requirement for withdrawal.</li><li><a href="https://www.peoplesbank.lk/term-deposite/" target="_blank" rel="noreferrer">People&#39;s Bank Term Deposits</a> describes a minor FD opened by a parent or guardian for children up to 18 and an advertised 0.5% premium over normal FD rates.</li><li><a href="https://www.plc.lk/products/fixed-deposits-savings/fixed-deposits-senehasa-minor/" target="_blank" rel="noreferrer">People&#39;s Leasing Senehasa Minor FD</a> describes guardian opening, 12–60 month terms, monthly or maturity interest payout, and closure by the child after reaching 18 subject to the certificate/NIC requirements.</li></ul><p><strong>Other special products.</strong> The existing catalogue research register contains senior/minor product notes and some fields such as <code>product_max_amount</code> and <code>tax_exempt</code>; those constraints are not yet represented as complete engine-enforced product rules. Special schemes may add aggregate caps across banks, age/residency requirements, guardian controls, restricted premature withdrawal, subsidy funding windows, product-specific tax treatment and special payout/renewal conditions.</p><h3 id="future-data-model-requirements-not-implemented-here" tabindex="-1">Future data-model requirements (not implemented here) <a class="header-anchor" href="#future-data-model-requirements-not-implemented-here" aria-label="Permalink to “Future data-model requirements (not implemented here)”">​</a></h3><p>Before activation, the product model likely needs explicit:</p><ul><li>Customer eligibility and evidence requirements.</li><li>Per-deposit and aggregate scheme caps, including scope across banks.</li><li>Scheme opening/closing windows and effective dates.</li><li>Tax treatment and the legal source for any exemption.</li><li>Early withdrawal/renewal consequences.</li><li>Guardian, joint-holder and maturity-access rules.</li><li>Product-specific payout and interest calculation terms.</li></ul><p>The generic age-segment checkbox must continue to mean “include these candidate products”; it is not identity or eligibility verification.</p><h2 id="_6-data-05-—-transfer-channel-modelling-research-only-keep-simplified-fees" tabindex="-1">6. DATA-05 — transfer channel modelling: research only, keep simplified fees <a class="header-anchor" href="#_6-data-05-—-transfer-channel-modelling-research-only-keep-simplified-fees" aria-label="Permalink to “6. DATA-05 — transfer channel modelling: research only, keep simplified fees”">​</a></h2><p>The current model intentionally uses a simplified bank-level fee approximation. No transfer-channel, customer-tier or privilege selector is being added in this pass.</p><h3 id="regulatory-baseline" tabindex="-1">Regulatory baseline <a class="header-anchor" href="#regulatory-baseline" aria-label="Permalink to “Regulatory baseline”">​</a></h3><p>CBSL Payment and Settlement Systems Circular No. 02 of 2025, dated 7 February 2025 and effective 15 February 2025, sets CEFTS maximum transaction fees:</p><ul><li>LKR 25 for internet banking, mobile banking and on-us ATM transfers.</li><li>LKR 100 for over-the-counter transfers and off-us ATM transfers.</li><li>LKR 25 for LPOPP transfers.</li><li>The standard CEFTS transaction-value limit is LKR 5 million, with defined LPOPP exceptions.</li></ul><p>Source: <a href="https://www.cbsl.gov.lk/sites/default/files/cbslweb_documents/laws/cdg/psd_circular_no_02_of_2025_e.pdf" target="_blank" rel="noreferrer">CBSL Circular No. 02 of 2025</a>. CBSL&#39;s <a href="https://www.cbsl.gov.lk/sites/default/files/Payments_Bulletin_3Q2025_e.pdf" target="_blank" rel="noreferrer">Payments Bulletin, Q3 2025</a> repeats the digital/OTC/off-us fee caps.</p><p>These are regulatory maximums for specified CEFTS channels, not proof that every bank charges the maximum or that all payment rails are CEFTS. They do not make an intra-bank transfer, SLIPS transfer, international transfer, OTC payment and mobile CEFTS transaction equivalent.</p><h3 id="bank-examples" tabindex="-1">Bank examples <a class="header-anchor" href="#bank-examples" aria-label="Permalink to “Bank examples”">​</a></h3><ul><li>HNB&#39;s tariff distinguishes CEFT transfers from SLIPS charges and describes own-bank transfers separately: <a href="https://www.hnb.lk/tariffs/other-product-tariffs" target="_blank" rel="noreferrer">HNB tariffs</a>.</li><li>MCB&#39;s 1 July 2026 schedule lists free internet/mobile transfers and a separate OTC CEFT charge: <a href="https://mcb.com.lk/wp-content/uploads/2026/06/Schedule-of-Bank-Charges-w.e.f-01-07-2026.pdf" target="_blank" rel="noreferrer">MCB schedule</a>.</li><li>Pan Asia&#39;s 2026 tariff distinguishes standard CEFT and Privilege Club pricing, and separates online from OTC: <a href="https://www.pabcbank.com/wp-content/uploads/2025/12/BANK-TARIFF-2026.pdf" target="_blank" rel="noreferrer">Pan Asia 2026 tariff</a>.</li></ul><p>The current <code>data/banks/banks.csv</code> captures some of these differences in source notes, but the engine still reduces them to a same-bank and domestic inter-bank fee. The existing DFCC note also records a bank-published LKR 30 value that appears to conflict with the CBSL digital CEFTS cap; this needs channel/scope reconciliation before changing the row.</p><h3 id="owner-approved-treatment-1" tabindex="-1">Owner-approved treatment <a class="header-anchor" href="#owner-approved-treatment-1" aria-label="Permalink to “Owner-approved treatment”">​</a></h3><p>Keep the simplified model. Preserve explicit “estimated transfer fee” wording and source notes. Do not silently substitute the regulatory maximum for a bank&#39;s actual tariff, infer privilege eligibility, or treat every transfer as CEFTS. A future channel model should be a separate product/UX change with explicit digital CEFT, OTC CEFT, SLIPS, internal transfer and international transfer choices, effective dates, account tiers and transaction limits.</p><h2 id="_7-data-06-—-dataset-review-economic-updates-and-schema-migrations" tabindex="-1">7. DATA-06 — dataset review, economic updates and schema migrations <a class="header-anchor" href="#_7-data-06-—-dataset-review-economic-updates-and-schema-migrations" aria-label="Permalink to “7. DATA-06 — dataset review, economic updates and schema migrations”">​</a></h2><h3 id="metadata-contract-implemented-on-this-branch" tabindex="-1">Metadata contract implemented on this branch <a class="header-anchor" href="#metadata-contract-implemented-on-this-branch" aria-label="Permalink to “Metadata contract implemented on this branch”">​</a></h3><p>The bank-to-dataset index, <code>data/fd_options/fd_options.csv</code>, now carries three independent fields:</p><ul><li><strong><code>dataset_reviewed_at</code>:</strong> date FD Cal last rechecked the bank&#39;s source material and mapped terms. This alone drives freshness warnings.</li><li><strong><code>dataset_updated_at</code>:</strong> date the economic bank/product data last materially changed (rate, tenor, minimum, payout terms, eligibility or another simulation input).</li><li><strong><code>dataset_schema_version</code>:</strong> version of the index/dataset row structure. Increment it for structural migrations such as adding, removing or renaming columns.</li></ul><p>A schema-only migration must preserve both dates exactly. A source recheck with no economic data change advances only the review date. A confirmed economic-data change advances the economic update date; if the source was reviewed as part of that change, update the review date as well. A migration, Git commit, file modification, release or deployment is not evidence that bank data changed or that a source was reviewed.</p><p>Product-level <code>source_effective_date</code> remains separate: it is the effective date stated by the bank for an individual product/rate row.</p><h3 id="owner-approved-thresholds" tabindex="-1">Owner-approved thresholds <a class="header-anchor" href="#owner-approved-thresholds" aria-label="Permalink to “Owner-approved thresholds”">​</a></h3><ul><li>0–179 days since source review: no age-based stale warning.</li><li>180–364 days: show “Review due / may be stale”.</li><li>365 days or more: show a stronger “Stale — verify directly with bank” warning.</li><li>Missing review date: show “Review date not recorded — freshness unverified”, not a fresh/green state.</li><li>Future or malformed review dates: show an invalid-metadata warning; do not silently treat them as current.</li></ul><p>Show a review-due warning after 180 days and a stronger stale warning after 365 days. These are catalogue-maintenance warnings, not claims that a bank&#39;s published rate has expired. A bank can change a rate the day after review; the source effective date remains a separate signal.</p><h3 id="implementation-and-remaining-work" tabindex="-1">Implementation and remaining work <a class="header-anchor" href="#implementation-and-remaining-work" aria-label="Permalink to “Implementation and remaining work”">​</a></h3><p>The metadata normalizer/merge helper, loader exposure, freshness classifier and bank-selector warnings are implemented. Contract tests verify that schema-version-only migrations preserve both dates and that unknown dates remain blank. All 29 bank index rows currently have blank review and economic-update dates; this is intentional until a maintainer actually rechecks each source. The remaining data task is a bank-by-bank source review, with defensible dates and evidence, not automatic date population.</p><p>See the <a href="./../data/BANK-DATA-METADATA.html">bank dataset metadata contract</a> and <a href="./IMPLEMENTATION-PLAN.html">implementation plan</a>.</p><h2 id="_8-web-sec-02-—-retain-github-pages" tabindex="-1">8. WEB-SEC-02 — retain GitHub Pages <a class="header-anchor" href="#_8-web-sec-02-—-retain-github-pages" aria-label="Permalink to “8. WEB-SEC-02 — retain GitHub Pages”">​</a></h2><p>GitHub Pages remains the hosting platform. The project cannot configure arbitrary origin response headers through the repository&#39;s Pages settings. Do not migrate hosting or introduce a proxy/CDN in this phase. Verify deployed response headers periodically and document any residual header limitation; keep application-level controls and dependency/workflow security checks.</p><h2 id="_9-search-01-—-browser-search-budget-calibration" tabindex="-1">9. SEARCH-01 — browser search budget calibration <a class="header-anchor" href="#_9-search-01-—-browser-search-budget-calibration" aria-label="Permalink to “9. SEARCH-01 — browser search budget calibration”">​</a></h2><p>Keep the current browser defaults (10,000 expanded states / 30 seconds) as the baseline. Do not reduce them simply because a short benchmark completes faster. The benchmark should compare 5k, 10k, 20k and uncapped state limits with 15/30/60-second budgets, across small, medium and hard scenarios.</p><p>Record:</p><ul><li>Runtime and peak memory where measurable.</li><li>Expanded states, beam/local pruning and stop reason.</li><li>Booking signatures, payout dates, fees, AIT, paid/outstanding outflows and closing values.</li><li>Whether search found a better candidate as budgets increased.</li><li>Whether the run exhausted the budget or completed normally.</li></ul><p>The browser must retain an explicit user-controlled longer/unlimited mode. A timeout is a resource stop, not proof that the best possible result was found. The default should balance responsiveness and useful result quality; no benchmark result should be extrapolated from a single runner or a single scenario.</p><p><strong>Execution status:</strong> the 12-point matrix was run on a harder 60-month, three-bank scenario with monthly inflows and strict outflows, plus a 24-month baseline control. All 12 harder-scenario runs returned the same financial result; the 5k state cap did not bind, and 15/30/60-second budgets explored progressively more states without improving the candidate. No run proved optimality. See <a href="./SEARCH-BUDGET-CALIBRATION.html">Search budget calibration</a>.</p><h2 id="_10-search-02-—-strategy-module-decomposition-plan" tabindex="-1">10. SEARCH-02 — strategy module decomposition plan <a class="header-anchor" href="#_10-search-02-—-strategy-module-decomposition-plan" aria-label="Permalink to “10. SEARCH-02 — strategy module decomposition plan”">​</a></h2><p>Do not perform a broad rewrite. Preserve existing parity/oracle tests and split only at stable responsibility boundaries:</p><ol><li><strong>Domain projection:</strong> candidate generation, payout/event projection, account liquidity and outflow obligations.</li><li><strong>Search state:</strong> immutable state shape, state key/equivalence, provenance and pending event representation.</li><li><strong>Ranking/pruning:</strong> scoped objective, goal objective, admissible bounds, beam priority and tie-breaks.</li><li><strong>Exploration orchestration:</strong> exhaustive branch-and-bound, bounded beam search and recursive GSS planning.</li><li><strong>Replay/authority:</strong> replay selected plans through the shared <code>SimulationRuntime</code>; runtime remains the only authority for actual event ordering, outflow settlement, booking and result construction.</li><li><strong>Diagnostics:</strong> expanded/pruned counts, budget termination, proof status and replay failures.</li></ol><p>Before moving code, map call graphs and import dependencies, identify duplicated projections and capture deterministic baselines. Avoid introducing a generic policy framework merely to share a few helpers. Extract one seam at a time with unchanged outputs and parity tests.</p><h2 id="_11-search-03-—-cross-strategy-and-outflow-parity" tabindex="-1">11. SEARCH-03 — cross-strategy and outflow parity <a class="header-anchor" href="#_11-search-03-—-cross-strategy-and-outflow-parity" aria-label="Permalink to “11. SEARCH-03 — cross-strategy and outflow parity”">​</a></h2><p>Treat the shared runtime as the authoritative executor. GSS, Absolute and Absolute+ may project future events, but they must not create independent authoritative outflow settlement. Their projections must preserve:</p><ul><li>Same-day ordering: inflows/FD cash flows/maturities, then outflows, then the next strategy decision.</li><li>Strict/defer/best-effort obligation semantics.</li><li>Source-account liquidity reserved for future obligations after consolidation transfers.</li><li>Future inflows and product payouts that legitimately restore liquidity.</li><li>Pending outflow amount, due date, account, and policy in state equivalence where those fields can change future decisions.</li><li>Actual payout dates and AIT-adjusted flows.</li><li>Replay through the runtime before a candidate is accepted as an actual result.</li></ul><p>Add parity fixtures whenever a new payout type, fee, eligibility rule, tax assumption or outflow rule is introduced. Preserve the existing legacy-oracle and scoped parity tests; do not relax them to make a new planner pass.</p><h2 id="_12-qa-01-qa-rep-01-—-browser-and-standalone-report-test-plan" tabindex="-1">12. QA-01 / QA-REP-01 — browser and standalone report test plan <a class="header-anchor" href="#_12-qa-01-qa-rep-01-—-browser-and-standalone-report-test-plan" aria-label="Permalink to “12. QA-01 / QA-REP-01 — browser and standalone report test plan”">​</a></h2><p>The owner approved browser-driven testing in CI for pushes and pull requests targeting <code>dev</code> or <code>main</code>. A small Playwright suite should cover:</p><ul><li>App startup and catalogue load at the production root and <code>/dev/web/</code> path.</li><li>Privacy preferences open/save/reopen and legal navigation.</li><li>One deterministic simulation, result rendering and report download.</li><li>Opening the downloaded HTML report independently (without the application page) and checking its core sections.</li><li>No uncaught page errors or failed same-origin requests.</li><li>Mobile viewport overflow, keyboard focus and reduced-motion behaviour.</li><li>Report print stylesheet and offline/no-external-runtime dependencies.</li></ul><p>Keep the suite deterministic and smoke-oriented. Do not introduce screenshot snapshots or a large browser matrix until basic smoke coverage is stable. Browser tests must run on PRs to <code>dev</code> and <code>main</code>, not only on a manual workflow dispatch.</p><h2 id="_13-legal-and-privacy-review-—-sri-lanka-first-with-mandatory-law-caveat" tabindex="-1">13. Legal and privacy review — Sri Lanka-first, with mandatory-law caveat <a class="header-anchor" href="#_13-legal-and-privacy-review-—-sri-lanka-first-with-mandatory-law-caveat" aria-label="Permalink to “13. Legal and privacy review — Sri Lanka-first, with mandatory-law caveat”">​</a></h2><h3 id="owner-provided-contact-route" tabindex="-1">Owner-provided contact route <a class="header-anchor" href="#owner-provided-contact-route" aria-label="Permalink to “Owner-provided contact route”">​</a></h3><ul><li>General, non-sensitive support: public <a href="https://github.com/aaron-fredrick/FD-Calculator/issues" target="_blank" rel="noreferrer">GitHub issues</a>.</li><li>Personal-data, privacy and confidential security matters: <code>a.n.r.fredrick@gmail.com</code>.</li><li>Never request or invite users to post financial account data, credentials or vulnerability details in public issues.</li></ul><h3 id="legal-framework-research" tabindex="-1">Legal framework research <a class="header-anchor" href="#legal-framework-research" aria-label="Permalink to “Legal framework research”">​</a></h3><p>The product is aimed at Sri Lankan fixed-deposit comparisons, so Sri Lankan law is a reasonable proposed governing-law choice for the terms. A governing-law clause cannot prevent proceedings in another jurisdiction where mandatory consumer/privacy law or a court&#39;s jurisdiction applies; it does not guarantee immunity from claims.</p><p>The legal pages should identify FD Cal as an independently maintained informational project, not a bank, deposit-taking business, financial adviser or transaction intermediary. Keep disclaimers factual: no deposits, account opening, money movement or bank instructions; outputs are estimates; users must verify rates, product eligibility, taxes and fees with banks and qualified professionals.</p><p><strong>Data protection timing is changing and must not be described using stale commencement assumptions.</strong> The Personal Data Protection (Amendment) Act No. 22 of 2025 was certified on 30 October 2025 (<a href="https://www.parliament.lk/en/home/parliament-news/view/4888" target="_blank" rel="noreferrer">Parliament notice</a>). The DPA&#39;s current notice says Gazette Extraordinary No. 2498/16 dated 22 July 2026 brings Sections 2–3 and Parts I and III into operation on 1 January 2027, while Parts II and VII are not yet active as at the notice date (<a href="https://dpa.gov.lk/notice.php" target="_blank" rel="noreferrer">DPA legal-status notice</a>). The legal pages should avoid claiming that every PDPA right, duty and penalty is already in force in November 2026; they should also be reviewed again when the 2027 commencement date arrives and when further gazettes are issued.</p><h3 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to “Limitations”">​</a></h3><p>This is engineering/product research, not a legal opinion. It cannot guarantee that an individual operator will not be sued or eliminate legal exposure. Before the site is used commercially, collects user accounts or server-side financial data, introduces analytics, or offers personalised recommendations, obtain a Sri Lankan lawyer&#39;s review of operator status, consumer protection, privacy obligations, tax wording, IP/licensing, liability clauses and cross-border exposure. The operator&#39;s full legal name and any business/entity details should not be published without a deliberate owner decision.</p>`,103)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};